// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.auth/** * NOUS — PIN storage interface (Module 12, Pillar 3). * * Strategy §12.3 — decouples [AuthenticationManager] from the storage backend. * *   - **Production** (`main` source set): [SqlCipherPinStorage] — persists *     the Argon2id hash to a SQLCipher-encrypted Room table. *   - **Unit tests** (`test` source set): `InMemoryPinStorage` — keeps the *     hash in-memory only; useful for fast non-Android tests. * * @see SqlCipherPinStorage */interface PinStorage {    /**     * Hash and store a PIN.     *     * @param pin the raw 4-6 digit PIN as a [CharArray]. Implementations     *   SHOULD zero the array after hashing (best-effort).     * @return true if the PIN was stored successfully.     * @throws IllegalArgumentException if the PIN is not 4-6 ASCII digits.     *   Implementations are responsible for validating; the production     *   impl ([SqlCipherPinStorage]) enforces this.     */    fun setPin(pin: CharArray): Boolean    /**     * Verify a PIN against the stored hash.     *     * @param pin the raw PIN as a [CharArray]. Implementations SHOULD zero     *   the array after verification.     * @return true on match, false on mismatch or when no PIN is set.     */    fun verifyPin(pin: CharArray): Boolean    /** True if a PIN has been set. */    fun isPinSet(): Boolean    /** Clear the stored PIN hash. */    fun clearPin()}